<script setup lang="ts">
import { computed, ref } from 'vue'
import { ArrowUp, ArrowDown, Money, ShoppingCart, UserFilled, Finished } from '@element-plus/icons-vue'
import TrendChart from '../components/TrendChart.vue'
import { appState } from '../data/repository'
import { currency } from '../utils'

const period=ref('近 7 天')
const paid=computed(()=>appState.orders.filter(order=>!['pending','cancelled','returned'].includes(order.status)))
const revenue=computed(()=>paid.value.reduce((sum,order)=>sum+order.total,0))
const metrics=computed(()=>[
  {label:'營業額',value:currency(revenue.value),change:'+18.6%',up:true,icon:Money,tone:'green'},
  {label:'訂單數',value:String(appState.orders.length),change:'+12.4%',up:true,icon:ShoppingCart,tone:'amber'},
  {label:'平均客單價',value:currency(Math.round(revenue.value/Math.max(1,paid.value.length))),change:'+5.2%',up:true,icon:Finished,tone:'blue'},
  {label:'轉換率',value:'3.84%',change:'-0.3%',up:false,icon:UserFilled,tone:'coral'},
])
const statusLabel:Record<string,string>={pending:'待付款',processing:'待出貨',shipped:'已出貨',completed:'已完成',cancelled:'已取消',returned:'已退貨'}
const chartValues=computed(()=>[18600,22400,20700,28600,25100,32400,revenue.value+4200])
</script>

<template>
  <section data-testid="dashboard">
    <div class="dashboard-toolbar"><p>最後更新：今天 10:30</p><el-segmented v-model="period" :options="['今日','近 7 天','近 30 天']" /></div>
    <div class="metric-grid"><article v-for="item in metrics" :key="item.label" class="metric-card"><div class="metric-icon" :class="item.tone"><el-icon><component :is="item.icon" /></el-icon></div><div><span>{{item.label}}</span><strong>{{item.value}}</strong><small :class="{negative:!item.up}"><el-icon><component :is="item.up?ArrowUp:ArrowDown" /></el-icon>{{item.change}} <i>較上期</i></small></div></article></div>
    <div class="dashboard-grid">
      <article class="panel revenue-panel"><header><div><h2>營業額趨勢</h2><p>近七日付款完成訂單</p></div><div class="legend"><i></i>營業額</div></header><TrendChart :labels="['08/22','08/23','08/24','08/25','08/26','08/27','今天']" :values="chartValues" /></article>
      <article class="panel category-panel"><header><div><h2>商品類別分布</h2><p>依銷售金額計算</p></div></header><div class="donut"><div><strong>68%</strong><span>服飾</span></div></div><ul><li><i class="c1"></i><span>服飾</span><strong>68%</strong></li><li><i class="c2"></i><span>包袋</span><strong>22%</strong></li><li><i class="c3"></i><span>生活</span><strong>10%</strong></li></ul></article>
      <article class="panel orders-panel"><header><div><h2>最新訂單</h2><p>需要留意的營運動態</p></div><router-link to="/orders">查看全部 →</router-link></header><div class="order-list"><router-link v-for="order in appState.orders.slice(0,4)" :key="order.id" :to="`/orders/${order.id}`"><span class="avatar">{{order.customerName.slice(0,1)}}</span><div><strong>{{order.customerName}}</strong><small>{{order.id}}</small></div><span class="status" :class="order.status">{{statusLabel[order.status]}}</span><strong>{{currency(order.total)}}</strong></router-link></div></article>
      <article class="panel ranking-panel"><header><div><h2>熱銷商品</h2><p>本期商品銷售排行</p></div></header><div v-for="(product,index) in appState.products" :key="product.id" class="rank-row"><strong>0{{index+1}}</strong><img :src="product.image" alt=""><div><b>{{product.name}}</b><span>{{product.category}} · {{product.skus.reduce((s,x)=>s+x.stock,0)}} 件庫存</span></div><em>{{currency(product.price)}}</em></div></article>
    </div>
  </section>
</template>

